-- Every EPA-regulated facility -- inspections, violations, and fines, 3.2M sites.
-- Auto-generated by scripts/gen_evidence_pages.py: 3,157,891 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("FAC_DATE_LAST_INSPECTION") as year, count(*) as records
from THE_LIBRARY.ENERGY_ENVIRONMENT.POLLUTION_ENFORCEMENT
where "FAC_DATE_LAST_INSPECTION" is not null
group by 1
order by 1
